// Public settings only. Select the API key credential on each HTTP Request node.
const settings = {
  crawlerUrl: 'http://mpf-crawler-api:8000',
  purchaseUrl: 'http://mpf-purchase:8000',
  valuationUrl: 'http://mpf-valuation:8000',
  provider: 'all',
  rollingDays: 7,
  maxPolls: 60,
  // Empty means today's Hong Kong date; use YYYY-MM-DD for manual recovery.
  asOfDate: '',
  // Empty means all accounts. Crawler always refreshes the chosen provider(s).
  accountId: '',
};
return [{ json: {
  ...settings,
  asOfDate: settings.asOfDate || $now.setZone('Asia/Hong_Kong').toISODate(),
  idempotencyKey: `mpf-n8n-${$workflow.id}-${$execution.id}`,
} }];

const result = $input.first().json;
if (!Number.isInteger(result.failed_events) || result.failed_events < 0 || !Number.isInteger(result.waiting_events) || result.waiting_events < 0) {
  throw new Error('Unexpected purchase response');
}
if (result.failed_events > 0) throw new Error(`Purchase processing reported ${result.failed_events} failed events; inspect Process purchases output`);
// Waiting events are retried on the next daily run. Keep the details in execution output.
return [{ json: { ...result, needsReview: result.waiting_events > 0 } }];
